/// <summary>
/// MPJ_34596_TransferOrderFinalisation Added coverNote, MetContinuousPermissionNotice,MetDangerousGoodsManifest
/// </summary>
[ExtensionOf(classStr(PrintMgmtNode_Invent))]
internal final class MetPrintMgmtNode_Invent_Extension
{
}

Method.Source:
    /// <summary>
    /// added more option to printmgmt
    /// </summary>
    /// <returns>list</returns>
    public List getDocumentTypes()
    {
        List metDocTypes = next getDocumentTypes();

        metDocTypes.addEnd(PrintMgmtDocumentType::MetCoverNote);
        metDocTypes.addEnd(PrintMgmtDocumentType::MetContinuousPermissionNotice);
        metDocTypes.addEnd(PrintMgmtDocumentType::MetDangerousGoodsManifest);

        metDocTypes.addEnd(PrintMgmtDocumentType::METTOLoadPlanningAid);
        metDocTypes.addEnd(PrintMgmtDocumentType::METTOLoadPlanningReport);
        metDocTypes.addEnd(PrintMgmtDocumentType::METTOShipment);
        metDocTypes.addEnd(PrintMgmtDocumentType::METTOMultimodalDangerousGoods);

        return metDocTypes;

    }
